from fractions import Fraction

def check_case(case):
    p = case['p']
    q = case['q']
    def nrm(x):
        return sum(t * t for t in x)
    def rot(x):
        a, b, c, d = x
        n = nrm(x)
        return [
            [Fraction(a*a + b*b - c*c - d*d, n), Fraction(2*(b*c - a*d), n), Fraction(2*(b*d + a*c), n)],
            [Fraction(2*(b*c + a*d), n), Fraction(a*a - b*b + c*c - d*d, n), Fraction(2*(c*d - a*b), n)],
            [Fraction(2*(b*d - a*c), n), Fraction(2*(c*d + a*b), n), Fraction(a*a - b*b - c*c + d*d, n)]
        ]
    def mul(X, Y):
        return [[sum(X[i][k] * Y[k][j] for k in range(3)) for j in range(3)] for i in range(3)]
    def tr(X):
        return [[X[j][i] for j in range(3)] for i in range(3)]
    def det(X):
        return (X[0][0] * (X[1][1] * X[2][2] - X[1][2] * X[2][1])
                - X[0][1] * (X[1][0] * X[2][2] - X[1][2] * X[2][0])
                + X[0][2] * (X[1][0] * X[2][1] - X[1][1] * X[2][0]))
    ident = [[1 if i == j else 0 for j in range(3)] for i in range(3)]
    if nrm(p) == 0 or nrm(q) == 0:
        claim_holds = False
    else:
        A = rot(p)
        B = rot(q)
        C = mul(mul(A, B), mul(tr(A), tr(B)))
        orth = mul(C, tr(C)) == ident
        unit_det = det(C) == 1
        cross = (p[2]*q[3] - p[3]*q[2], p[3]*q[1] - p[1]*q[3], p[1]*q[2] - p[2]*q[1])
        parallel = cross == (0, 0, 0)
        implication = (not parallel) or (C == ident)
        claim_holds = orth and unit_det and implication
    return bool(claim_holds == case['expect_claim'])

def check_case(case):
    from math import gcd
    from itertools import permutations

    # --- sub-operator A: non-coprime residue recombination inside Z/lcm ---
    moduli = case['moduli']
    residues = case['residues']
    ok = True
    L = 1
    x = 0
    for m, r in zip(moduli, residues):
        if m <= 0:
            ok = False
            break
        g = gcd(L, m)
        d = (r - x) % m
        if d % g != 0:
            ok = False
            break
        m1 = L // g
        m2 = m // g
        dd = d // g
        inv = 0
        if m2 > 1:
            for t in range(1, m2):
                if (m1 * t) % m2 == 1:
                    inv = t
                    break
        k = (dd * inv) % m2
        x = (x + L * k) % (L * m2)
        L = L * m2
    pairwise = True
    for i in range(len(moduli)):
        for j in range(i + 1, len(moduli)):
            if (residues[i] - residues[j]) % gcd(moduli[i], moduli[j]) != 0:
                pairwise = False
    criterion_agrees = (pairwise == ok)
    sol_verified = True
    if ok:
        for m, r in zip(moduli, residues):
            if x % m != r % m:
                sol_verified = False
        if x < 0 or x >= L:
            sol_verified = False
    expected_x = (x % L) if ok else 0

    # --- sub-operator B: fraction-free elimination vs sign expansion ---
    def sign_expansion(mat):
        n = len(mat)
        if n == 0:
            return 1
        total = 0
        for perm in permutations(range(n)):
            inv = 0
            for i in range(n):
                for j in range(i + 1, n):
                    if perm[i] > perm[j]:
                        inv += 1
            prod = 1
            for i in range(n):
                prod = prod * mat[i][perm[i]]
            total = total + (prod if inv % 2 == 0 else -prod)
        return total

    def fraction_free(mat):
        n = len(mat)
        if n == 0:
            return 1, True
        A = [row[:] for row in mat]
        sign = 1
        prev = 1
        exact = True
        for k in range(n - 1):
            if A[k][k] == 0:
                sw = -1
                for i in range(k + 1, n):
                    if A[i][k] != 0:
                        sw = i
                        break
                if sw == -1:
                    return 0, True
                A[k], A[sw] = A[sw], A[k]
                sign = -sign
            for i in range(k + 1, n):
                for j in range(k + 1, n):
                    num = A[i][j] * A[k][k] - A[i][k] * A[k][j]
                    if num % prev != 0:
                        exact = False
                    A[i][j] = num // prev
                A[i][k] = 0
            prev = A[k][k]
        return sign * A[n - 1][n - 1], exact

    det_ff, divisibility_exact = fraction_free(case['matrix'])
    det_se = sign_expansion(case['matrix'])

    # --- sub-operator C: extremal tail bound, cross-multiplied, integer only ---
    a, b = case['ratio']
    Q = case['Q']
    bound_ok = False
    if b > 0 and Q >= 1:
        for q in range(1, Q + 1):
            p0 = (q * a) // b
            for p in (p0 - 1, p0, p0 + 1):
                r = q * a - p * b
                if r < 0:
                    r = -r
                if (Q + 1) * r <= b:
                    bound_ok = True

    # --- sub-operator D: defect of a non-commuting integer frame pair ---
    def mul2(X, Y):
        return [[X[0][0] * Y[0][0] + X[0][1] * Y[1][0], X[0][0] * Y[0][1] + X[0][1] * Y[1][1]],
                [X[1][0] * Y[0][0] + X[1][1] * Y[1][0], X[1][0] * Y[0][1] + X[1][1] * Y[1][1]]]

    AB = mul2(case['pair_a'], case['pair_b'])
    BA = mul2(case['pair_b'], case['pair_a'])
    defect = 0
    for i in range(2):
        for j in range(2):
            t = AB[i][j] - BA[i][j]
            if t < 0:
                t = -t
            defect = defect + t

    claim_holds = (criterion_agrees
                   and sol_verified
                   and divisibility_exact
                   and det_ff == det_se
                   and bound_ok
                   and defect == case['claimed_defect']
                   and case['claimed_det'] == det_se
                   and case['claimed_consistent'] == ok
                   and case['claimed_x'] == expected_x)
    return bool(claim_holds == case['expect_claim'])

