                ok = False
    trc = C[0][0] + C[1][1] + C[2][2]
    dd = 3 - trc
    frob = sum((C[i][j]-I3[i][j])**2 for i in range(3) for j in range(3))
    if frob != 2*dd:
        ok = False
    if dd < 0 or dd > 4:
        ok = False
    b1, c1, d1 = p[1], p[2], p[3]
    b2, c2, d2 = q[1], q[2], q[3]
