from fractions import Fraction
from math import gcd


def _ext_gcd(a, b):
    old_r, r = a, b
    old_s, s = 1, 0
    old_t, t = 0, 1
    while r != 0:
        q = old_r // r
        old_r, r = r, old_r - q * r
        old_s, s = s, old_s - q * s
        old_t, t = t, old_t - q * t
    return old_r, old_s, old_t


def _inv_mod(a, m):
    if m == 1:
        return 0
    g, s, _ = _ext_gcd(a % m, m)
    if g != 1:
        return None
    return s % m


def _convergents(cf):
    pm2, pm1 = 0, 1
    qm2, qm1 = 1, 0
    out = []
    for a in cf:
        p = a * pm1 + pm2
        q = a * qm1 + qm2
        out.append((p, q))
        pm2, pm1 = pm1, p
        qm2, qm1 = qm1, q
    return out


def _bareiss3(mat):
    a = [[mat[i][j] for j in range(3)] for i in range(3)]
    prev = 1
    for k in range(2):
        if a[k][k] == 0:
            return None
        for i in range(k + 1, 3):
            for j in range(k + 1, 3):
                num = a[i][j] * a[k][k] - a[i][k] * a[k][j]
                if num % prev != 0:
                    return None
                a[i][j] = num // prev
        prev = a[k][k]
    return a[2][2]


def _pairwise_ok(ms, rs):
    for i in range(len(ms)):
        for j in range(i + 1, len(ms)):
            if (rs[j] - rs[i]) % gcd(ms[i], ms[j]) != 0:
                return False
    return True


def _crt(ms, rs):
    x = 0
    L = 1
    for i in range(len(ms)):
        m = ms[i]
        r = rs[i]
        g = gcd(L, m)
        d = r - x
        if d % g != 0:
            return None
        m2 = m // g
        if m2 > 1:
            inv = _inv_mod(L // g, m2)
            if inv is None:
                return None
            t = ((d // g) * inv) % m2
        else:
            t = 0
        x = x + L * t
        L = L * m2
        x = x % L
    return (x, L)


def check_case(case):
    cf = case['cf']
    clocks = case['clocks']
    residues = case['residues']
    conv = _convergents(cf)
    if len(conv) < 3 or len(clocks) < 3 or len(residues) != len(clocks):
        return bool(False == case['expect_claim'])
    P = conv[-1][0]
    Q = conv[-1][1]
    alpha = Fraction(P, Q)
    env_ok = True
    for n in range(0, len(conv) - 2):
        pn, qn = conv[n]
        qn1 = conv[n + 1][1]
        gap = abs(alpha - Fraction(pn, qn))
        if not (gap * qn * qn1 < 1):
            env_ok = False
    det_ok = True
    for n in range(0, len(conv) - 1):
        if abs(conv[n][0] * conv[n + 1][1] - conv[n + 1][0] * conv[n][1]) != 1:
            det_ok = False
    p_a, q_a = conv[-3]
    p_b, q_b = conv[-2]
    p_c, q_c = conv[-1]
    mat = [[p_a, p_b, p_c], [q_a, q_b, q_c], [1, 1, 1]]
    det3 = (mat[0][0] * (mat[1][1] * mat[2][2] - mat[1][2] * mat[2][1])
            - mat[0][1] * (mat[1][0] * mat[2][2] - mat[1][2] * mat[2][0])
            + mat[0][2] * (mat[1][0] * mat[2][1] - mat[1][1] * mat[2][0]))
    if _bareiss3(mat) != det3:
        det_ok = False
    L = 1
    for m in clocks:
        L = L * (m // gcd(L, m))
    pair_ok = _pairwise_ok(clocks, residues)
    merged = _crt(clocks, residues)
    crt_ok = pair_ok and (merged is not None)
    if (merged is not None) != pair_ok:
        crt_ok = False
    if merged is None:
        crt_ok = False
    else:
        x, LL = merged
        if LL != L or not (0 <= x < L):
            crt_ok = False
        for i in range(len(clocks)):
            if x % clocks[i] != residues[i] % clocks[i]:
                crt_ok = False
    det_crt_ok = True
    dmods = [det3 % m for m in clocks]
    merged_det = _crt(clocks, dmods)
    if merged_det is None:
        det_crt_ok = False
    else:
        if merged_det[1] != L:
            det_crt_ok = False
        if merged_det[0] != det3 % L:
            det_crt_ok = False
    claim = env_ok and det_ok and crt_ok and det_crt_ok
    return bool(claim == case['expect_claim'])

