    i = 0
    L = len(bits)
    while i < L:
        if bits[i] == 1:
            j = i
            while j + 1 < L and bits[j + 1] == 1:
                j += 1
            runs.append([i, j])
            i = j + 1
        else:
            i += 1

    cover_sorted = sorted([list(iv) for iv in cover])
    cover_ok = (cover_sorted == runs)

    ones_positions = {idx for idx, b in enumerate(bits) if b == 1}
    covered_positions = set()
    for lo, hi in cover_sorted:
        for p in range(lo, hi + 1):
            covered_positions.add(p)
    union_ok = (covered_positions == ones_positions)

    def tree_sum(seq):
        if len(seq) == 0:
            return 0
        if len(seq) == 1:
            return seq[0]
        mid = len(seq) // 2
        return tree_sum(seq[:mid]) + tree_sum(seq[mid:])

    ones = tree_sum(bits)
    checksum_ok = (ones == case['checksum'])

    run_lengths = [hi - lo + 1 for lo, hi in runs]
    total_pairs = ones * (ones - 1) // 2
    intra = sum(rl * (rl - 1) // 2 for rl in run_lengths)
    inter = 0
    for a, b in itertools.combinations(run_lengths, 2):
        inter += a * b
    bilinear_ok = (intra + inter == total_pairs) and (case['intra'] == intra) and (case['inter'] == inter) and (case['runs'] == len(runs))

    r2 = n * n + k * k
    tail_ok = (r2 > 1)
    if total_pairs > 0:
        zeta_eq = Fraction(2 * inter, total_pairs * (r2 + 1))
    else:
        zeta_eq = Fraction(0, 1)
    zeta_ok = tail_ok and (Fraction(3, 20) <= zeta_eq <= Fraction(3, 10))

    claim_holds = cover_ok and union_ok and checksum_ok and bilinear_ok and zeta_ok
    return bool(claim_holds == case['expect_claim'])

