def check_case(case):
    def rot(w, x, y, z):
        N = w*w + x*x + y*y + z*z
        return [[Fraction(w*w+x*x-y*y-z*z, N), Fraction(2*(x*y-w*z), N), Fraction(2*(x*z+w*y), N)],
                [Fraction(2*(x*y+w*z), N), Fraction(w*w-x*x+y*y-z*z, N), Fraction(2*(y*z-w*x), N)],
                [Fraction(2*(x*z-w*y), N), Fraction(2*(y*z+w*x), N), Fraction(w*w-x*x-y*y+z*z, N)]]
    def mul(A, B):
        return [[sum(A[i][k]*B[k][j] for k in range(3)) for j in range(3)] for i in range(3)]
    def tp(A):
        return [[A[j][i] for j in range(3)] for i in range(3)]
    def det(A):
        return (A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])
                - A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])
                + A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0]))
    ident = [[Fraction(int(i == j)) for j in range(3)] for i in range(3)]
    ok = True
    acc = 0
    for b in case['bits']:
        acc = acc ^ b
    if acc != case['xor_claim']:
        ok = False
    if gcd(case['m'], case['n']) != case['gcd_claim']:
        ok = False
    p = case['p']
    q = case['q']
    if p > q and q > 0:
        X = Fraction(p*p-q*q, p*p+q*q)
        Y = Fraction(2*p*q, p*p+q*q)
        t = 1 - X
        if X*X + Y*Y != 1:
            ok = False
        if t / (1 - t) != Fraction(2*q*q, p*p-q*q):
            ok = False
        if Fraction(1, 6) * t * t != Fraction(2*q**4, 3*(p*p+q*q)**2):
            ok = False
    qa = case['qa']
    qb = case['qb']
    Na = sum(c*c for c in qa)
    Nb = sum(c*c for c in qb)
    A = rot(qa[0], qa[1], qa[2], qa[3])
