    if mul(C, tp(C)) != ident:
        ok = False
    if det(C) != 1:
        ok = False
    K = (Na*Nb)**2
    for row in C:
        for c in row:
            if (c*K).denominator != 1:
                ok = False
    u = qa[1:]
    v = qb[1:]
    cr = (u[1]*v[2]-u[2]*v[1], u[2]*v[0]-u[0]*v[2], u[0]*v[1]-u[1]*v[0])
    parallel = (cr[0] == 0 and cr[1] == 0 and cr[2] == 0)
    if parallel and C != ident:
        ok = False
    if case['iff_mode'] == 1:
        if (C == ident) != parallel:
            ok = False
    return bool(ok == case['expect_claim'])

def check_case(case):
    from fractions import Fraction
    from math import gcd, isqrt
    import itertools

    def inv_mod(a, m):
        old_r, r = a % m, m
        old_s, s = 1, 0
        while r:
            q = old_r // r
            old_r, r = r, old_r - q * r
            old_s, s = s, old_s - q * s
        if old_r != 1:
            return None
        return old_s % m

    def merge(m1, r1, m2, r2):
        g = gcd(m1, m2)
        if (r2 - r1) % g != 0:
            return None
        b = m2 // g
        d = (r2 - r1) // g
        if b == 1:
            t = 0
        else:
            iv = inv_mod((m1 // g) % b, b)
            if iv is None:
                return None
            t = (d % b) * iv % b
        L = m1 * b
        return (L, (r1 + m1 * t) % L)

    def det_bareiss(M):
        A = [row[:] for row in M]
        sz = len(A)
        sign = 1
        prev = 1
        for k in range(sz - 1):
            if A[k][k] == 0:
                sw = -1
                for i in range(k + 1, sz):
                    if A[i][k] != 0:
                        sw = i
                        break
                if sw < 0:
                    return 0
                A[k], A[sw] = A[sw], A[k]
                sign = -sign
            if prev == 0:
                return 0
            for i in range(k + 1, sz):
                for j in range(k + 1, sz):
                    A[i][j] = (A[i][j] * A[k][k] - A[i][k] * A[k][j]) // prev
                A[i][k] = 0
            prev = A[k][k]
        return sign * A[sz - 1][sz - 1]

    def det_perm(M):
        sz = len(M)
        total = 0
        for perm in itertools.permutations(range(sz)):
            inv = 0
            for i in range(sz):
                for j in range(i + 1, sz):
                    if perm[i] > perm[j]:
                        inv += 1
            term = 1
            for i in range(sz):
                term *= M[i][perm[i]]
            if inv % 2 == 0:
                total += term
            else:
                total -= term
        return total

    claim = True
    mods = [int(v) for v in case['mods']]
    res = [int(v) for v in case['resids']]
    nclk = len(mods)
    pair_ok = True
    for i in range(nclk):
        for j in range(i + 1, nclk):
            if (res[i] - res[j]) % gcd(mods[i], mods[j]) != 0:
                pair_ok = False
    st = (1, 0)
    merged_ok = True
    for idx in range(nclk):
        out = merge(st[0], st[1], mods[idx], res[idx])
        if out is None:
            merged_ok = False
            break
        st = out
    if pair_ok != merged_ok:
        claim = False
    if not merged_ok:
        return bool(False == case['expect_claim'])
    L, x = st
    if L != int(case['claimed_lcm']):
        claim = False
    if x != int(case['claimed_phase']):
        claim = False
    if not (0 <= x < L):
        claim = False
    for idx in range(nclk):
        if x % mods[idx] != res[idx] % mods[idx]:
            claim = False
    if int(case['mesh']) != L * int(case['scale']):
        claim = False
    if int(case['phase']) % L != x:
        claim = False
    M = [[int(v) for v in row] for row in case['matrix']]
    sz = len(M)
    if sz == 0 or any(len(row) != sz for row in M):
        return bool(False == case['expect_claim'])
    db = det_bareiss(M)
    dp = det_perm(M)
    if db != dp:
        claim = False
    if dp != int(case['claimed_det']):
        claim = False
    scaled = [[L * v for v in row] for row in M]
    if det_perm(scaled) != (L ** sz) * dp:
        claim = False
    ra = [row[:] for row in M]
    ri = int(case['row_add_i'])
    rj = int(case['row_add_j'])
    mult = int(case['row_add_mult'])
    if 0 <= ri < sz and 0 <= rj < sz and ri != rj:
        for c in range(sz):
            ra[ri][c] += mult * ra[rj][c]
        if det_perm(ra) != dp:
            claim = False
    else:
        claim = False
    prefix = [int(v) for v in case['prefix']]
    conv = []
    p_prev, p_cur = 0, 1
    q_prev, q_cur = 1, 0
    for a in prefix:
        p_prev, p_cur = p_cur, a * p_cur + p_prev
        q_prev, q_cur = q_cur, a * q_cur + q_prev
        conv.append((p_cur, q_cur))
    if len(conv) < 4:
        claim = False
    else:
        alpha = Fraction(conv[-1][0], conv[-1][1])
        hi = len(conv) - 3
        certs = 0
        for idx in range(hi + 1):
            p, q = conv[idx]
            qn = conv[idx + 1][1]
            err = alpha - Fraction(p, q)
            if not (abs(err) * q * qn < 1):
                claim = False
            if idx % 2 == 0 and not (err > 0):
                claim = False
            if idx % 2 == 1 and not (err < 0):
                claim = False
            certs += 1
        if certs < 1:
            claim = False
        best = None
        bidx = -1
        for idx in range(len(conv)):
            p, q = conv[idx]
            err = alpha - Fraction(p, q)
            val = (q ** 4) * err * err
            if best is None or val < best:
                best = val
                bidx = idx
        if bidx != int(case['cert_index']):
            claim = False
        if not (5 * best < 1):
            claim = False
    npt = int(case['n'])
    kpt = int(case['k'])
    r2 = npt * npt + kpt * kpt
    if r2 <= 1:
        claim = False
    else:
        t = Fraction(2, r2 + 1)
        kap = t / (1 - t)
        if kap != Fraction(2, r2 - 1):
            claim = False
        zs = int(case['teeth'][0])
        zr = int(case['teeth'][1])
        if zs != r2 - 1 or zr != r2 + 1:
            claim = False
        if t * zr != 2 or kap * zs != 2:
            claim = False
        if Fraction(int(case['claimed_kappa_num']), int(case['claimed_kappa_den'])) != kap:
            claim = False
        if Fraction(1, 6) * t * t != Fraction(2, 3 * (r2 + 1) ** 2):
            claim = False
        m = r2
        X = Fraction(m * m - 1, m * m + 1)
        Y = Fraction(2 * m, m * m + 1)
        if X * X + Y * Y != 1:
            claim = False
        if (2 * npt) ** 2 + (2 * kpt) ** 2 + (r2 - 1) ** 2 != (r2 + 1) ** 2:
            claim = False
        if isqrt((r2 + 1) ** 2) != r2 + 1:
            claim = False
    return bool(claim == case['expect_claim'])
